return {["fb222_01"]={["dsc"]=[[这里是一处狭小的山涧，山泉自山顶落下，一块巨石嵌在正中，被水流冲刷成上尖下圆之状，山泉水也被其一分为二。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_01]],["item1"]=[[22bsitem02]],["item2"]=[[23zftx03js01]],["leftDown"]=[[fb222_04]],["name"]=[[破水路]],["permission"]=2,["rightDown"]=[[fb222_05]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_02"]={["dsc"]=[[山洞幽暗密闭不知通向何方，据传这里是山神的居所，也有说这里是神兽苍夔的巢穴。以前曾有村民闯入，但无一例外，皆失去踪影，因此村中人对山洞为忌惮和敬畏，不敢轻易进入。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_02]],["item1"]=[[23Zftxjscf01]],["leftDown"]=[[fb222_06]],["name"]=[[山洞]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_03"]={["dsc"]=[[此地崖壁之上被人工开凿出一处山洞，这里也是村中主要的矿物来源，洞口附近放着很多木架、推车等工具，地上也是满是碎石。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_03]],["item1"]=[[22qftx01jscf01]],["name"]=[[开山洞]],["permission"]=2,["rightDown"]=[[fb222_07]],["role1"]=[[22qjqzcf21]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_04"]={["dsc"]=[[此地位于山顶一侧，因其地势之高在特殊天气时能只手触云，景色甚美。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_04]],["item1"]=[[22qjqzcf27]],["item2"]=[[22qjzhangjqitem01]],["name"]=[[揉云崖]],["permission"]=2,["right"]=[[fb222_05]],["rightUp"]=[[fb222_01]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_05"]={["dsc"]=[[这里是村中研习掌法之人修炼场所之一，空地上放着许多特制的摇木桩，有些已经残破损毁了。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_05]],["left"]=[[fb222_04]],["leftUp"]=[[fb222_01]],["name"]=[[摧木台]],["permission"]=2,["rightDown"]=[[fb222_09]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_06"]={["dsc"]=[[这里是一处泉眼，泉水由此而出流向山下，途中与其他泉水汇合最终流入碧水湖，碧水泉入口甘甜清凉，是村中重要的水源。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_06]],["item1"]=[[22qjqzcf29]],["item2"]=[[22zftx01jscf01]],["leftDown"]=[[fb222_11]],["name"]=[[碧水泉]],["permission"]=2,["rightUp"]=[[fb222_02]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_07"]={["dsc"]=[[这里堆放着许多废弃石料形成了一座座小山包，松松散散好像随时都会滑落。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_07]],["item1"]=[[22qjquanjqitem01]],["item2"]=[[23qfdj8cf02]],["leftUp"]=[[fb222_03]],["name"]=[[杂石堆]],["permission"]=2,["right"]=[[fb222_08]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_08"]={["down"]=[[fb222_19]],["dsc"]=[[这里被人工挖掘而出一个不小的水潭，从山上开采的矿石会在此处清洗后按照品质送往下面的场地。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_08]],["left"]=[[fb222_07]],["name"]=[[洗矿池]],["permission"]=2,["rightDown"]=[[fb222_14]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_09"]={["dsc"]=[[这里的山腰处有两个岔路口，一条通向幽暗的紫藤林，另一条则通向山顶。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_09]],["leftDown"]=[[fb222_17]],["leftUp"]=[[fb222_05]],["name"]=[[山腰]],["permission"]=2,["right"]=[[fb222_10]],["role1"]=[[22bsnpc25]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_10"]={["dsc"]=[[这里生长着大片茂盛的紫藤树，树藤垂下密闭紧凑，其中还生有荆棘，除此外这里还盘踞着各种毒蛇毒虫，叫人生畏。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_10]],["item1"]=[[22qjqzcf14]],["left"]=[[fb222_09]],["name"]=[[紫藤林]],["permission"]=2,["right"]=[[fb222_11]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_100"]={["dsc"]=[[这里的树木繁茂，枝叶遮天，致使此处不见天日，瘴气遮目，难辨东西。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_100]],["item1"]=[[23qftx03js01]],["name"]=[[深山树林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb222_98]],["visible"]=1},["fb222_11"]={["dsc"]=[[这里生长着大片茂盛的紫藤树，树藤垂下密闭紧凑，其中还生有荆棘，除此外这里还盘踞着各种毒蛇毒虫，叫人生畏。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_11]],["left"]=[[fb222_10]],["name"]=[[紫藤林]],["permission"]=2,["rightUp"]=[[fb222_06]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_12"]={["dsc"]=[[这里地面上满是碎石，很是难走，每走一步都会发出石头碰撞的响声。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_12]],["item1"]=[[22bsitem01]],["item2"]=[[23qftxjscf01]],["name"]=[[碎石坡]],["permission"]=2,["right"]=[[fb222_13]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_13"]={["dsc"]=[[这里是某座山底部突出的岩壁，因其常年爆露在外早已风华，平常人用手一搬便会从崖壁上拽下一大块碎石板，也正因如此，村中老人常常告诫孩童不要靠近此处，以免发生意外。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_13]],["item1"]=[[22qfjql2jscf02]],["left"]=[[fb222_12]],["name"]=[[碎石崖]],["permission"]=2,["rightDown"]=[[fb222_18]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_14"]={["dsc"]=[[这里堆放着很多石材，或方或圆，或厚或薄，这里堆放的石料可供村中直接使用。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_14]],["item1"]=[[22qjqzcf23]],["item2"]=[[22qftx01jscf02]],["leftDown"]=[[fb222_19]],["leftUp"]=[[fb222_08]],["name"]=[[石料场]],["permission"]=2,["right"]=[[fb222_15]],["rightDown"]=[[fb222_20]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_15"]={["dsc"]=[[此地用青石和原木搭建了很多煤窖，用来存贮开采出来的煤炭以供村中冬天使用。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_15]],["item1"]=[[22qfaj6jscf02]],["left"]=[[fb222_14]],["name"]=[[煤窖]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_16"]={["down"]=[[fb222_21]],["dsc"]=[[村中的祠堂，里面放着很多排位，在另一面墙上还挂着一幅巨大的族谱，族谱上写着很多人名。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_16]],["item1"]=[[22qjbsitem11]],["name"]=[[祠堂]],["permission"]=2,["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_17"]={["dsc"]=[[一条蜿蜒的小路通向山上，因离学堂较近，所以在路旁修缮了很多木头栏杆，以防发生意外。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_17]],["leftDown"]=[[fb222_22]],["name"]=[[登山路]],["permission"]=2,["rightUp"]=[[fb222_09]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_18"]={["dsc"]=[[村外通往山上的碎石路，路上的碎石都是常年累月积攒而来，走上去会发出喀拉喀拉的响声。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_18]],["item1"]=[[23qjjqjs7cf01]],["leftUp"]=[[fb222_13]],["name"]=[[碎石路]],["permission"]=2,["right"]=[[fb222_19]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_19"]={["down"]=[[fb222_31]],["dsc"]=[[这里是专门处理石料的场地，粗糙不规则的石料在此经由工具加工后便成为了许多建筑用到的基石，除此之外一些雕塑、摆设也是由此而出。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_19]],["item1"]=[[22qjqzcf25]],["item2"]=[[22qjqf4item01]],["item3"]=[[22qjqf4item03]],["item4"]=[[22qjqf4item04]],["item5"]=[[22qfjql2jscf01]],["item6"]=[[22qfdj5jscf01]],["item7"]=[[23qfdj7cf03]],["item8"]=[[23qfdj8cf01]],["left"]=[[fb222_18]],["name"]=[[石工坊]],["permission"]=2,["right"]=[[fb222_20]],["rightUp"]=[[fb222_14]],["stepMusic"]=[[mudiban]],["up"]=[[fb222_08]],["visible"]=1},["fb222_20"]={["dsc"]=[[宽敞的空地上用黄泥和青石搭建了数个熔炉，这里是铁矿初步加工的地方，在此村民将矿石熔炼成铁水，凝固冷却后运往铁匠铺加工成平日需要的工具。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_20]],["item1"]=[[22qfdj5jscf02]],["left"]=[[fb222_19]],["leftUp"]=[[fb222_14]],["name"]=[[熔炼炉]],["permission"]=2,["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_21"]={["down"]=[[fb222_33]],["dsc"]=[[村中最大的一栋建筑，从外看非常气派，三楼屋檐下还挂着一些灯笼。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_21]],["item1"]=[[22zfdj6jscf02]],["item2"]=[[23zfdj7cf01]],["item3"]=[[23zfdj8cf01]],["name"]=[[议事堂]],["permission"]=2,["right"]=[[fb222_22]],["stepMusic"]=[[mudiban]],["up"]=[[fb222_16]],["visible"]=1},["fb222_22"]={["dsc"]=[[这里是村中供孩子学习的地方，每天清晨这里都会传出朗朗的读书声。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_22]],["item1"]=[[22qjzhangjqitem02]],["left"]=[[fb222_21]],["name"]=[[学堂]],["permission"]=2,["right"]=[[fb222_23]],["rightUp"]=[[fb222_17]],["role1"]=[[22bsnpc23]],["role2"]=[[22bsnpc24]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_23"]={["dsc"]=[[这里原是苗云的居所，自从师傅失踪后村中大小事宜便都由她来处理，于是苗云将原来的居所扩建，如今的闲云院虽不及议事厅那么宽敞，但容纳前来办事的村民还是绰绰有余的。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_23]],["item1"]=[[22qjqzcf26]],["item2"]=[[22qjqzcf28]],["item3"]=[[22qjqzcf30]],["item4"]=[[22llscq03]],["item5"]=[[22qjzhangjqitem03]],["item6"]=[[23zfjql3jscf01b]],["left"]=[[fb222_22]],["name"]=[[闲云院]],["permission"]=2,["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_24"]={["dsc"]=[[这是村中的铁匠铺，铁匠铺的烟囱中日升腾着白烟，村中近乎所有的工具铁器都是由此而出，而铁匠铺的匠人们也无比细心，从院中一角堆叠的参器便能看出。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_24]],["item1"]=[[22qjqzcf20]],["item2"]=[[22qjqzcf22]],["item3"]=[[22qjqzcf24]],["item4"]=[[22llscq01]],["item5"]=[[22qjtuijqitem02]],["item6"]=[[22qftx01jscf03]],["item7"]=[[22qfaj6jscf01]],["item8"]=[[23qfjql3jscf01a]],["leftDown"]=[[fb222_31]],["name"]=[[铁匠铺]],["permission"]=2,["right"]=[[fb222_25]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_25"]={["dsc"]=[[这里是村中的木匠铺，院落中堆放着一些处理后的木材和原木，村中大大小小的家具都是由此而出，其中的木匠手艺更是精湛让人赞叹。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_25]],["left"]=[[fb222_24]],["name"]=[[木匠铺]],["permission"]=2,["rightDown"]=[[fb222_32]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_26"]={["dsc"]=[[万福记中有各种糕点饴糖，但主要营收来自其惊艳的糖画，据掌柜说，他们祖上凭借这门手艺曾在御膳房大放异彩，因其糖画、糖雕美艳绝伦深受皇上喜爱，至于是如何落入此地掌柜只字不提。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_26]],["leftDown"]=[[fb222_34]],["name"]=[[万福记]],["permission"]=1,["right"]=[[fb222_27]],["role1"]=[[22bsnpc14]],["role2"]=[[22bsnpc15]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_27"]={["dsc"]=[[这里是村中的油铺，油铺即兜售成品油也收购原材料，收来的原材料会在后院工坊内加工直至榨出成品再装桶售卖。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_27]],["left"]=[[fb222_26]],["name"]=[[油铺]],["permission"]=1,["right"]=[[fb222_28]],["role1"]=[[22bsnpc10]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_28"]={["dsc"]=[[这里是村中的肉铺，很多猎户都会将猎物皮肉分离，多出的肉会卖到此处，肉铺除了售卖生肉外，还会卖一些加工后的吃食，像果木熏肉、碳烤糊肉、蜜卤烧肉这些在村中也大受欢迎。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_28]],["item1"]=[[22qjqzcf16]],["item2"]=[[22tfdj5jscf03]],["left"]=[[fb222_27]],["name"]=[[肉铺]],["permission"]=1,["rightDown"]=[[fb222_35]],["role1"]=[[22bsnpc07]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_29"]={["dsc"]=[[这里成开着无数鲜花，离此老远便能闻见扑鼻的香气，花田之中放着很多蜂箱。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_29]],["item1"]=[[22bsitem04]],["item2"]=[[23zhijql3jscf03]],["leftDown"]=[[fb222_37]],["name"]=[[飞蜂路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_30"]={["dsc"]=[[说是古井，其实为一处地下潭水，为取水修建了一条石板长阶，时间久了石板上遍生青苔，腿法稍差的人都不敢来此取水。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_30]],["item1"]=[[22tx1003cf]],["name"]=[[千阶古井]],["permission"]=2,["right"]=[[fb222_31]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_31"]={["down"]=[[fb222_49]],["dsc"]=[[前是石工坊，后是刨木场，右临圩市，左通古井。路边树木茂盛，幽暗谧静。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_31]],["item1"]=[[22qjbsitem02]],["item2"]=[[22qjtuijqitem05]],["item3"]=[[22tfjql2jscf01]],["left"]=[[fb222_30]],["name"]=[[岔路口]],["permission"]=2,["rightDown"]=[[fb222_38]],["rightUp"]=[[fb222_24]],["role1"]=[[22bsnpc29]],["role2"]=[[22bsnpc19]],["stepMusic"]=[[jiaobu]],["up"]=[[fb222_19]],["visible"]=1},["fb222_32"]={["dsc"]=[[村西面的集市，这里常摆放一些工具、皮料的摊铺，有些在林中发现的怪石、木料也会在此售卖。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_32]],["item1"]=[[22qftx01jscf04]],["leftDown"]=[[fb222_39]],["leftUp"]=[[fb222_25]],["name"]=[[西圩市]],["permission"]=2,["right"]=[[fb222_33]],["role1"]=[[22bsnpc09]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_33"]={["down"]=[[fb222_45]],["dsc"]=[[这里非常宽敞，陈列着许多练武器具和一排排的木桩。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_33]],["item1"]=[[22qjbsitem09]],["item2"]=[[22qjbsitem10]],["item3"]=[[22tx1002cf]],["left"]=[[fb222_32]],["name"]=[[习武场]],["permission"]=1,["right"]=[[fb222_34]],["stepMusic"]=[[jiaobu]],["up"]=[[fb222_21]],["visible"]=1},["fb222_34"]={["dsc"]=[[这里是村东一处空地，也是村中的集市，只要天气好很多村民都会在此摆摊，不仅可以银两购买还可以以物换物，不过以物换物的就要看卖家需要什么了，也常会有买卖双方发生口角。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_34]],["item1"]=[[22qjbsitem01]],["left"]=[[fb222_33]],["name"]=[[东圩市]],["permission"]=1,["rightDown"]=[[fb222_40]],["rightUp"]=[[fb222_26]],["role1"]=[[22bsnpc05]],["role2"]=[[22bsnpc06]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_35"]={["dsc"]=[[这里是村中售卖酒饮的地方，虽酒类不多，但可以说各个都是精品。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_35]],["item1"]=[[22qjqianzhicf07]],["leftDown"]=[[fb222_42]],["leftUp"]=[[fb222_28]],["name"]=[[酒垆]],["permission"]=1,["role1"]=[[22bsnpc08]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_36"]={["dsc"]=[[这片林子中生长着很多珍贵的药草，医馆的大夫曾试着将这里特有的药草带回医馆种植但都以失败告终，于是大夫劝说村民来此采药不要过量以免破坏此地的自然循环，好在村民对此都很是理解，芝草林经过这么多年依然是一幅无人侵扰的样子。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_36]],["item1"]=[[23zhitxjscf01]],["leftDown"]=[[fb222_43]],["name"]=[[芝草林]],["permission"]=2,["right"]=[[fb222_37]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_37"]={["dsc"]=[[这片林子中生长着很多珍贵的药草，医馆的大夫曾试着将这里特有的药草带回医馆种植但都以失败告终，于是大夫劝说村民来此采药不要过量以免破坏此地的自然循环，好在村民对此都很是理解，芝草林经过这么多年依然是一幅无人侵扰的样子。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_37]],["item1"]=[[23zhitx03js01]],["left"]=[[fb222_36]],["leftDown"]=[[fb222_44]],["name"]=[[芝草林]],["permission"]=2,["rightUp"]=[[fb222_29]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_38"]={["dsc"]=[[村中的猎户会将打来的兽皮在此售卖，而皮匠则会将兽皮加工制作成日常所需的物品。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_38]],["leftUp"]=[[fb222_31]],["name"]=[[皮匠铺]],["permission"]=2,["right"]=[[fb222_39]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_39"]={["dsc"]=[[这家铺子的掌柜是从远方大城逃难而来的，她技艺独特，凡是经她手中做出的衣服都漂亮非常。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_39]],["left"]=[[fb222_38]],["name"]=[[成衣铺]],["permission"]=2,["rightUp"]=[[fb222_32]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_40"]={["dsc"]=[[杂货铺内宽阔无比，里面摆设很多货架，上面的商品琳琅满目，这都要归功于杂货铺的掌柜，自从开店以来她便经常带着伙计外出采买，这才使得铺中的商品种类繁多，可以说是应有尽有。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_40]],["leftUp"]=[[fb222_34]],["name"]=[[杂货铺]],["permission"]=1,["right"]=[[fb222_41]],["role1"]=[[22bsnpc13]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_41"]={["dsc"]=[[在每年农收之际，村民收获的粮谷多数都会售卖于此，而米铺中除了加工后的精粮外还会售卖一些米糕、米饼等等之类的小吃，在村中很受欢迎。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_41]],["left"]=[[fb222_40]],["name"]=[[米铺]],["permission"]=1,["right"]=[[fb222_42]],["role1"]=[[22bsnpc12]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_42"]={["dsc"]=[[这家面馆看似平平无奇但其中却暗藏一绝，面馆的秦掌柜有一手绝学，凡是经她手揉出的面团做出的面条口感丰富无比，外加秘制高汤满满一碗散发着让人垂涎的香味，其店中的“珍味龙须面”更为一绝，在村中倍受喜爱。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_42]],["item1"]=[[22qjqzcf31]],["item2"]=[[22qjzf4item01]],["item3"]=[[22qjzf4item02]],["item4"]=[[22qjzf4item03]],["item5"]=[[22zfdj5jscf01]],["left"]=[[fb222_41]],["name"]=[[面馆]],["permission"]=1,["rightUp"]=[[fb222_35]],["role1"]=[[22bsnpc11]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_43"]={["dsc"]=[[这片林子中生长着很多珍贵的药草，医馆的大夫曾试着将这里特有的药草带回医馆种植但都以失败告终，于是大夫劝说村民来此采药不要过量以免破坏此地的自然循环，好在村民对此都很是理解，芝草林经过这么多年依然是一幅无人侵扰的样子。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_43]],["leftDown"]=[[fb222_48]],["name"]=[[芝草林]],["permission"]=2,["right"]=[[fb222_44]],["rightUp"]=[[fb222_36]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_44"]={["dsc"]=[[这片林子中生长着很多珍贵的药草，医馆的大夫曾试着将这里特有的药草带回医馆种植但都以失败告终，于是大夫劝说村民来此采药不要过量以免破坏此地的自然循环，好在村民对此都很是理解，芝草林经过这么多年依然是一幅无人侵扰的样子。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_44]],["item1"]=[[23qjjqjs7cf02]],["left"]=[[fb222_43]],["name"]=[[芝草林]],["permission"]=2,["rightUp"]=[[fb222_37]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_45"]={["down"]=[[fb222_52]],["dsc"]=[[一棵巨大的古榕树，垂下的榕树须扎进土里也生得健壮，有一树成林之势。在夏日此处实为遮阴避暑的好地，也常有村民在此乘凉闲聊。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_45]],["item1"]=[[22qjjq5cf01]],["name"]=[[古榕树]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb222_33]],["visible"]=1},["fb222_46"]={["down"]=[[fb222_53]],["dsc"]=[[这里是医馆的药房，里面放着几个硕大的木柜，柜上分成无数方格，每一个方格内都单独放着一种药材。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_46]],["item1"]=[[22qjqzcf12]],["item2"]=[[22qjbsitem04]],["item3"]=[[22qjbsitem05]],["item4"]=[[22qjqzcf12a]],["item5"]=[[22qjqzcf12b]],["item6"]=[[22llscq04]],["item7"]=[[22qjzhijqitem01]],["item8"]=[[22zhijql2jscf02]],["item9"]=[[22zhidj6jscf01]],["name"]=[[药房]],["permission"]=2,["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_47"]={["dsc"]=[[这里是通往芝草林的土坡，这里没有修缮道路，葱郁的草地中只有一条浅浅的痕迹，经由此处便可到底芝草林。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_47]],["item1"]=[[22qjzhif4item01]],["item2"]=[[22qjzhif4item02]],["item3"]=[[22qjzhif4item03]],["leftDown"]=[[fb222_57]],["name"]=[[芝草坡]],["permission"]=2,["right"]=[[fb222_48]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_48"]={["dsc"]=[[这里是通往芝草林的土坡，这里没有修缮道路，葱郁的草地中只有一条浅浅的痕迹，经由此处便可到底芝草林。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_48]],["left"]=[[fb222_47]],["name"]=[[芝草坡]],["permission"]=2,["rightUp"]=[[fb222_43]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_49"]={["dsc"]=[[这里是处理原木的木场，运来的原木经过处理会分成不同品级的木材备用。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_49]],["item1"]=[[22tfdj6jscf01]],["name"]=[[刨木场]],["permission"]=2,["right"]=[[fb222_50]],["rightDown"]=[[fb222_64]],["stepMusic"]=[[jiaobu]],["up"]=[[fb222_31]],["visible"]=1},["fb222_50"]={["dsc"]=[[这里四周空旷树木很少，村民将砍伐运回的原木堆积在此，在阳光的暴晒下蒸发其水分后运往刨木场加工。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_50]],["item1"]=[[23tfdj7cf01]],["left"]=[[fb222_49]],["name"]=[[晒木场]],["permission"]=2,["right"]=[[fb222_51]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_51"]={["dsc"]=[[窖体采用独特工艺建造，以地道的形式将热量运送至晒木厂以便更为快捷高效的发挥作用。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_51]],["left"]=[[fb222_50]],["name"]=[[烘干窖]],["permission"]=2,["rightDown"]=[[fb222_66]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_52"]={["down"]=[[fb222_67]],["dsc"]=[[这里放着一个宽敞的比武擂台，旁边还有很多放置器械的木架，若是有什么重大活动此处会非常热闹。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_52]],["item1"]=[[22qjjq2item01]],["item2"]=[[23zhidj7cf01]],["name"]=[[比武场]],["permission"]=1,["right"]=[[fb222_53]],["stepMusic"]=[[jiaobu]],["up"]=[[fb222_45]],["visible"]=1},["fb222_53"]={["dsc"]=[[这里是村中的医馆，走进此处便能闻见药香，门口的两根竹子上挂着两个木牌，上联：只要世上人莫病。下联：何愁架上药生尘。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_53]],["item1"]=[[22zhidj5jscf02]],["item2"]=[[23qfdj7cf02]],["left"]=[[fb222_52]],["name"]=[[医馆]],["permission"]=2,["right"]=[[fb222_54]],["role1"]=[[22bsnpc20]],["role2"]=[[22bsnpc21]],["role3"]=[[22bsnpc22]],["stepMusic"]=[[mudiban]],["up"]=[[fb222_46]],["visible"]=1},["fb222_54"]={["dsc"]=[[正房厢庑游廊，悉皆小巧别致，院中随处之树木山石皆在。一时进入正室，只见绣女丽服挨坐，手中绣盘佳景尽显，让人赞赏。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_54]],["item1"]=[[22qjzhitxitem05]],["left"]=[[fb222_53]],["name"]=[[绣坊]],["permission"]=2,["right"]=[[fb222_55]],["role1"]=[[22bsnpc27]],["role2"]=[[22bsnpc28]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_55"]={["dsc"]=[[这里是村中的织坊，织工将棉、麻、蚕丝、绒等原材料回收后便会在此根据材料织成线，再由线编织成布料售卖，所用材料不同制成的布料也有所不同，掌柜再根据布料品质排成三六九等标价后售卖而出。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb222_55]],["item1"]=[[22qjjq3item01]],["item2"]=[[22qjjq3item02]],["left"]=[[fb222_54]],["name"]=[[织坊]],["permission"]=2,["right"]=[[fb222_56]],["role1"]=[[22bsnpc30]],["role2"]=[[22bsnpc31]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb222_56"]={["dsc"]=[[这里种着一大片桑树，是村中饲养桑蚕的地方，桑蚕结茧便是蚕丝的主要来源，因其产量不多，所以村中的蚕丝制品价格略高，渐渐的村中蚕丝制品变成了嫁娶这种重大事件中不可缺少的一物。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_56]],["item1"]=[[22qjqzcf13]],["item2"]=[[22qjzhijqitem03]],["left"]=[[fb222_55]],["name"]=[[桑树田]],["permission"]=2,["right"]=[[fb222_57]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_57"]={["dsc"]=[[溪水自山上留下最终流入湖中，溪水甘甜清凉，站在岸边能清楚的看见水中穿游的鱼儿虾蟹，这里也是村中孩童常来的游玩之地，溪水不深，流速平缓。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_57]],["item1"]=[[22qjzhitxitem01]],["item2"]=[[23qjjqjs6cf01]],["left"]=[[fb222_56]],["name"]=[[碧水溪]],["permission"]=2,["right"]=[[fb222_58]],["rightUp"]=[[fb222_47]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_58"]={["dsc"]=[[这里是医馆的药草田，栽种着许多常见的草药。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_58]],["item1"]=[[22zhitx01jscf01]],["item2"]=[[23zhidj8cf01]],["left"]=[[fb222_57]],["name"]=[[药草田]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_59"]={["dsc"]=[[这里通向山顶方向，地面上满是毫无规则的碎石，每走一步都要万分小心，否则后果难以想象。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_59]],["item1"]=[[22bsitem05]],["item2"]=[[23tftxjscf01]],["name"]=[[登天阶]],["permission"]=2,["right"]=[[fb222_60]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_60"]={["dsc"]=[[这里树木繁茂阳光稀少，因此阴暗潮湿，弥漫着如雾瘴气，但其中鸟兽众多，因此村中猎人很是喜欢来此打猎，但因为树根错综复杂，山路崎岖，只有腿法较好的猎人才会来此。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_60]],["item1"]=[[22qjtuitxitem01]],["left"]=[[fb222_59]],["name"]=[[雾林]],["permission"]=2,["right"]=[[fb222_61]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_61"]={["dsc"]=[[这里树木繁茂阳光稀少，因此阴暗潮湿，弥漫着如雾瘴气，但其中鸟兽众多，因此村中猎人很是喜欢来此打猎，但因为树根错综复杂，山路崎岖，只有腿法较好的猎人才会来此。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_61]],["item1"]=[[23tftx03js01]],["left"]=[[fb222_60]],["name"]=[[雾林]],["permission"]=2,["rightDown"]=[[fb222_62]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_62"]={["dsc"]=[[这里树木繁茂阳光稀少，因此阴暗潮湿，弥漫着如雾瘴气，但其中鸟兽众多，因此村中猎人很是喜欢来此打猎，但因为树根错综复杂，山路崎岖，只有腿法较好的猎人才会来此。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_62]],["leftUp"]=[[fb222_61]],["name"]=[[雾林]],["permission"]=2,["right"]=[[fb222_63]],["rightDown"]=[[fb222_76]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_63"]={["dsc"]=[[这里是雾林中的一处山崖，从此望去，能看清整片碧水湖。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_63]],["left"]=[[fb222_62]],["name"]=[[陡崖]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_64"]={["dsc"]=[[这里的杉木生长茂盛，地面堆积着厚厚的落叶。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_64]],["item1"]=[[22qjbsitem03]],["item2"]=[[23tfdj8cf01]],["leftUp"]=[[fb222_49]],["name"]=[[杉木林]],["permission"]=2,["right"]=[[fb222_65]],["role1"]=[[22bsnpc19]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_65"]={["dsc"]=[[这里的杉木生长茂盛，地面堆积着厚厚的落叶。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_65]],["item1"]=[[22qjtuijqitem01]],["left"]=[[fb222_64]],["name"]=[[杉木林]],["permission"]=2,["right"]=[[fb222_66]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_66"]={["dsc"]=[[这里长着一望无际的芦苇，芦苇足有一人之高，就算是成年人贸然进入也会迷路，虽是如此村中也会有淘气的孩子三五结伴来此寻找水鸟巢穴偷拿鸟蛋。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb222_66]],["item1"]=[[22tx2003cf]],["item2"]=[[22zfjql2jscf01]],["left"]=[[fb222_65]],["leftDown"]=[[fb222_79]],["leftUp"]=[[fb222_51]],["name"]=[[芦苇荡]],["permission"]=2,["right"]=[[fb222_67]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb222_67"]={["down"]=[[fb222_80]],["dsc"]=[[这里经常有人前来参拜打扫，就连屋顶瓦片上的落叶都寥寥无几，诺大的木制庙屋被刷上了朱红色染料，远看即神秘又庄严。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb222_67]],["item1"]=[[22qjbsitem06]],["item2"]=[[22qjbsitem07]],["item3"]=[[22qjbsitem08]],["item4"]